"use strict";(globalThis.webpackChunkgrc||=[]).push([[90058],{19277(e){e.exports=JSON.parse('{"citeKey":"he2014performanceaware","slug":"he-2014-performance-aware-5536","title":"Performance-Aware Data Placement in Hybrid Parallel File Systems","authors":["S. He","X.-H. Sun","B. Feng","K. Feng"],"venue":"14th International Conference on Algorithms and Architectures for Parallel Processing (ICA3PP), Dalian, China","type":"Conference","entryType":"inproceedings","date":"August, 2014","year":2014,"era":"iit","month":8,"doi":"10.1007/978-3-319-11197-1_43","abstract":"Hybrid parallel file systems (PFS), which consist of both HDD and SSD servers, provide a promising solution for data-intensive applications. In this study, we propose a performance-aware data place- ment (PADP) strategy to enable efficient data layout in hybrid PFSs. The basic idea of PADP is to dispatch data on different file servers with adaptive varied-size file stripes based on the server storage performance. By using an effective data access cost model and a linear programming optimization method, the appropriate stripe sizes for each file server are determined effectively. We have implemented PADP within OrangeFS, a widely used parallel file system in HPC domain. Experimental results of representative benchmark show that PADP can significantly improve the I/O performance of hybrid PFSs.","hasAbstract":true,"lede":"In this study, we propose a performance-aware data place- ment (PADP) strategy to enable efficient data layout in hybrid PFSs.","links":{"pdf":"https://grc.iit.edu/papers/2014/he-2014-performance-aware-5536.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he","feng-kun"]}')}}]);